<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNIFCO Customer Action Center</title><style>:root{font-family:Inter,Arial,sans-serif;--navy:#06275c;--red:#e20b24;--bg:#f6f8fb;--line:#e1e6ee;--muted:#6d7b90}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#071f4d}.wrap{max-width:1300px;margin:auto;padding:26px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.top h1{margin:0 0 5px;font-size:25px}.top p{margin:0;color:var(--muted);font-size:11px}.badge{padding:7px 10px;border-radius:999px;background:#e9eff8;font-size:9px;font-weight:800}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:16px}.metric,.panel{background:#fff;border:1px solid var(--line);border-radius:12px}.metric{padding:14px}.metric span{font-size:9px;color:var(--muted)}.metric b{display:block;font-size:24px;margin-top:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.panel{padding:16px}.panel h2{font-size:14px;margin:0 0 12px}.item{padding:10px 0;border-bottom:1px solid #edf1f5;display:flex;justify-content:space-between;gap:10px}.item:last-child{border-bottom:0}.item b{font-size:10px}.item small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.action{font-size:9px;font-weight:800;color:#225d9c;text-decoration:none}.empty{padding:20px;text-align:center;color:var(--muted);font-size:10px}.back{display:inline-flex;margin-top:16px;background:var(--navy);color:#fff;padding:9px 13px;border-radius:8px;text-decoration:none;font-size:10px;font-weight:800}@media(max-width:900px){.summary{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:520px){.summary{grid-template-columns:1fr}.wrap{padding:14px}}</style></head><body><main class="wrap"><div class="top"><div><h1>Action Required From You</h1><p>Phase 2 customer workflow center · {{ str_replace('_',' ',$role) }}</p></div><span class="badge">{{ $total }} open actions</span></div><section class="summary"><div class="metric"><span>Quotations</span><b>{{ $quotations->count() }}</b></div><div class="metric"><span>Work Acceptance</span><b>{{ $workOrders->count() }}</b></div><div class="metric"><span>Invoices Due</span><b>{{ $invoices->count() }}</b></div><div class="metric"><span>Contract Renewals</span><b>{{ $contracts->count() }}</b></div><div class="metric"><span>Unread Messages</span><b>{{ $unread }}</b></div></section><div class="grid"><section class="panel"><h2>Quotations Awaiting Your Decision</h2>@forelse($quotations as $q)<div class="item"><div><b>{{ $q->quotation_no }} · {{ number_format((float)$q->amount,2) }} {{ $q->currency }}</b><small>{{ $q->status }}</small></div><a class="action" href="{{ route('customer.section','quotations') }}">Review →</a></div>@empty<div class="empty">No quotation decisions required.</div>@endforelse</section><section class="panel"><h2>Completed Work Awaiting Acceptance</h2>@forelse($workOrders as $wo)<div class="item"><div><b>{{ $wo->work_order_no }} · {{ $wo->asset?->name }}</b><small>Completed {{ $wo->completed_at?->diffForHumans() }}</small></div><a class="action" href="{{ route('customer.work-acceptance.index') }}">Review →</a></div>@empty<div class="empty">No work orders awaiting acceptance.</div>@endforelse</section><section class="panel"><h2>Invoices Requiring Attention</h2>@forelse($invoices as $invoice)<div class="item"><div><b>{{ $invoice->document_no }} · {{ number_format((float)$invoice->open_amount,2) }} {{ $invoice->currency }}</b><small>Due {{ $invoice->due_date?->format('Y-m-d') }}</small></div><a class="action" href="{{ route('customer.section','invoices') }}">Open →</a></div>@empty<div class="empty">No invoices require attention.</div>@endforelse</section><section class="panel"><h2>Contracts Approaching Renewal</h2>@forelse($contracts as $contract)<div class="item"><div><b>{{ $contract->contract_no }} · {{ $contract->title }}</b><small>Ends {{ $contract->ends_on?->format('Y-m-d') }}</small></div><a class="action" href="{{ route('customer.section','contracts') }}">Review →</a></div>@empty<div class="empty">No contract renewals due soon.</div>@endforelse</section></div><a class="back" href="{{ route('customer.portal') }}">← Back to Customer 360</a></main></body></html>